"""Bounded LAN throughput of generated bytes; no private files or credentials travel."""
from pathlib import Path
import socket,subprocess,time,json,threading
root=Path(__file__).resolve().parents[2]
opts=['-i',str(root/'ssh-access/id_ed25519'),'-o','IdentitiesOnly=yes','-o','BatchMode=yes','-o','ConnectTimeout=8','-o','HostKeyAlias=iMac-de-xuso-2.local','-o','StrictHostKeyChecking=yes','-o','UserKnownHostsFile='+str(root/'ssh-access/known_hosts')]
host='xuso@iMac-de-xuso-2.local'
local=subprocess.check_output(['ipconfig','getifaddr','en0'],text=True).strip()
remote=subprocess.check_output(['ssh']+opts+[host,'ipconfig getifaddr en1'],text=True).strip()
results=[]
for direction in ['down','up','up','down']:
 server=socket.socket();server.bind((local,0));server.listen(1);server.settimeout(15)
 port=server.getsockname()[1]
 code='''import socket,time,json
s=socket.socket();s.settimeout(15);s.connect((%r,%d));payload=b'P'*65536;n=0;start=time.time()
if %r=='down':
 while True:
  b=s.recv(65536)
  if not b:break
  n+=len(b)
else:
 while time.time()-start<4:
  s.sendall(payload);n+=len(payload)
 s.shutdown(socket.SHUT_WR)
print(json.dumps({'bytes':n,'seconds':time.time()-start}))
s.close()
'''%(local,port,direction)
 import shlex
 proc=subprocess.Popen(['ssh']+opts+[host,'python -c '+shlex.quote(code)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
 conn,addr=server.accept();server.close()
 if addr[0]!=remote:conn.close();proc.terminate();raise RuntimeError('Unexpected LAN peer')
 conn.settimeout(10);start=time.monotonic();count=0;payload=b'P'*65536
 if direction=='down':
  while time.monotonic()-start<4:conn.sendall(payload);count+=len(payload)
  conn.shutdown(socket.SHUT_WR)
 else:
  while True:
   data=conn.recv(65536)
   if not data:break
   count+=len(data)
 elapsed=time.monotonic()-start;conn.close();out,err=proc.communicate(timeout=10)
 if proc.returncode:raise RuntimeError(err)
 peer=json.loads(out);result={'direction':direction,'bytes':count,'seconds':elapsed,'Mbps':count*8/elapsed/1e6,'peer':peer};results.append(result);print(json.dumps(result),flush=True)
(root/'build/network-2026-10-08.json').write_text(json.dumps(results,indent=2))
